  runModel = function(sp=consumers,rs=resources,c=C,k=K,y=Y,t=T,use=U,prod=P){
    validate(sp,rs,c,k,y,t,use,prod);let tm=Math.max(.1,+$("tMax").value),sample=Math.max(.01,+$("sample").value),h=Math.max(.0005,Math.min(.03,sample/6,tm/5000)),state=sp.map(q=>q.n0).concat(rs.map(q=>q.r0)),time=0,next=sample,pts=[{t:0,v:state.slice()}],stableStart=null,stable=null,window=Math.max(sample*3,tm*.08);
    while(time<tm-1e-10){let dt=Math.min(h,tm-time),f=z=>deriv(z,sp,rs,c,k,y,t,use,prod),k1=f(state),k2=f(state.map((v,j)=>v+dt*k1[j]/2)),k3=f(state.map((v,j)=>v+dt*k2[j]/2)),k4=f(state.map((v,j)=>v+dt*k3[j]));state=state.map((v,j)=>Math.max(0,v+dt*(k1[j]+2*k2[j]+2*k3[j]+k4[j])/6));time+=dt;if(state.some(v=>!Number.isFinite(v)||v>1e9))throw Error("Numerical divergence: Check the parameters, Resource Transformation yield and units");let d=f(state),rel=Math.max(...d.map(Math.abs))/Math.max(1,...state);if(rel<1e-7){if(stableStart===null)stableStart=time;if(stable===null&&time-stableStart>=window)stable=stableStart}else stableStart=null;if(time+1e-8>=next||time+1e-8>=tm){pts.push({t:Math.min(time,tm),v:state.slice()});next+=sample}}
    return{pts,stable,sp:sp.map(q=>({...q})),rs:rs.map(q=>({...q})),c:c.map(r=>r.slice()),k:k.map(r=>r.slice()),y:y.map(r=>r.slice()),t:cloneTensor(t),use:cloneMatrix(use),prod:cloneMaskTensor(prod)};
  };

  generateKnown = function(){
    const cfg=Object.fromEntries(distMeta.map(q=>[q[1],()=>sampleKnownCfg(q)]));
    consumers=Array.from({length:n},(_,i)=>({name:`Consumer ${i+1}`,n0:cfg.n0(),m:cfg.mort()}));
    resources=Array.from({length:m},(_,a)=>({name:a===0?"Primary resource":`Metabolite ${a}`,r0:cfg.r0(),s:cfg.supply(),d:cfg.dilution()}));
    normalizeResourceTotals(resources,resourceTotal("r0",true),resourceTotal("supply",true));
    C=Array.from({length:n},(_,i)=>Array.from({length:m},(_,a)=>U[i][a]?cfg.uptake():0));K=Array.from({length:n},(_,i)=>Array.from({length:m},(_,a)=>U[i][a]?cfg.half():0));Y=Array.from({length:n},(_,i)=>Array.from({length:m},(_,a)=>U[i][a]?cfg.yield():0));T=Array.from({length:n},(_,i)=>Array.from({length:m},(_,b)=>Array.from({length:m},(_,a)=>P[i][b][a]&&U[i][a]?cfg.conversion():0)));validate();render();result=null;setStatus(`Generated parameters from the current utilization and production structures; R₀ and S were normalized to the specified totals`);
  };
  randomModel = function(){
    let cfg=Object.fromEntries(distMeta.map(q=>[q[1],()=>sampleCfg(q)])),sp=Array.from({length:n},(_,i)=>({name:`Consumer ${i+1}`,n0:cfg.n0(),m:cfg.mort()})),rs=Array.from({length:m},(_,a)=>({name:a===0?"Primary resource":`Metabolite ${a}`,r0:cfg.r0(),s:cfg.supply(),d:cfg.dilution()})),c=Array.from({length:n},()=>Array.from({length:m},()=>cfg.uptake())),k=Array.from({length:n},()=>Array.from({length:m},()=>cfg.half())),y=Array.from({length:n},()=>Array.from({length:m},()=>cfg.yield())),t=makeTensor(n,m,cfg.conversion);normalizeResourceTotals(rs,resourceTotal("r0",false),resourceTotal("supply",false));return{sp,rs,c,k,y,t};
  };

  params = function(res){
    let p=[["response_type",$("responseType")?.value||"monod"]];res.sp.forEach((q,i)=>p.push([`N${i+1}_name`,q.name],[`N${i+1}_N0`,q.n0],[`N${i+1}_m`,q.m]));res.rs.forEach((q,a)=>p.push([`R${a+1}_name`,q.name],[`R${a+1}_R0`,q.r0],[`R${a+1}_S`,q.s],[`R${a+1}_delta`,q.d]));for(let i=0;i<res.sp.length;i++)for(let a=0;a<res.rs.length;a++)p.push([`Use_${i+1}_${a+1}`,res.use[i][a]?1:0],[`c_${i+1}_${a+1}`,res.c[i][a]],[`K_${i+1}_${a+1}`,res.k[i][a]],[`Y_${i+1}_${a+1}`,res.y[i][a]]);for(let i=0;i<res.sp.length;i++)for(let b=0;b<res.rs.length;b++)for(let a=0;a<res.rs.length;a++)p.push([`Produce_${i+1}_${b+1}_${a+1}`,res.prod[i][b][a]?1:0],[`Dconv_${i+1}_${b+1}_${a+1}`,res.t[i][b][a]]);return p;
  };
  exportCSV = async function(){if(!result)simulate();let x=rowsFor(result,1),stamp=new Date().toISOString().replace(/[:.]/g,"-").slice(0,19);await saveCSV([x.head,...x.rows].map(r=>r.map(csvCell).join(",")).join("\n"),`consumer_resource_metabolites_single_${stamp}.csv`);setStatus("Single-simulation CSV generated")};
  batch = async function(){
    let count=clamp(Math.round(+$("batchCount").value||50),2,1000),all=[],head=null,btn=$("batchBtn");btn.disabled=true;try{for(let run=1;run<=count;run++){let z=randomModel(),rec=runModel(z.sp,z.rs,z.c,z.k,z.y,z.t,z.use,z.prod),x=rowsFor(rec,run);head??=x.head;all.push(...x.rows);$("progress").style.width=run/count*100+"%";$("batchInfo").textContent=`Simulating ${run} / ${count}`;if(run%5===0)await new Promise(r=>setTimeout(r,0))}let stamp=new Date().toISOString().replace(/[:.]/g,"-").slice(0,19);await saveCSV([head,...all].map(r=>r.map(csvCell).join(",")).join("\n"),`consumer_resource_metabolites_random_${count}_${stamp}.csv`);$("batchInfo").textContent=`Completed ${count}  simulations, CSV Generated`;setStatus("Repeated random simulation completed")}finally{btn.disabled=false}
  };
  applyBulk = function(){
    sync();let key=$("bulkParam").value,value=+$("bulkValue").value;if(!Number.isFinite(value)||value<0)throw Error("The common value must be nonnegative");let ii=parseTargets($("bulkConsumers").value,n,"Consumer"),aa=parseTargets($("bulkResources").value,m,"Input Resource"),bb=parseTargets($("bulkOutputs").value,m,"Output Resource");if(key==="n0")ii.forEach(i=>consumers[i].n0=value);else if(key==="mort")ii.forEach(i=>consumers[i].m=value);else if(key==="r0")aa.forEach(a=>resources[a].r0=value);else if(key==="supply")aa.forEach(a=>resources[a].s=value);else if(key==="dilution")aa.forEach(a=>resources[a].d=value);else if(key==="conversion")ii.forEach(i=>bb.forEach(b=>aa.forEach(a=>{if(P[i][b][a]&&U[i][a])T[i][b][a]=value})));else{let A=key==="uptake"?C:key==="half"?K:Y;ii.forEach(i=>aa.forEach(a=>{if(U[i][a])A[i][a]=value}))}validate();render();result=null;setStatus(`Set ${key} to ${value} for the selected enabled pathways`);
  };

  const existingModelBoundary = document.querySelector(".method-card .note.warn");
  if(existingModelBoundary) existingModelBoundary.innerHTML = `<b>Model boundaries:</b> Dᵢβα is a net resource-transformation yield proportional to uptake flux. The current model does not separately resolve intracellular metabolism, active secretion, passive leakage, or release through cell lysis. For strict mass conservation, constrain the Dᵢβα values associated with each input resource using a consistent basis such as molar mass or carbon equivalents.`;
  const methodBlocks=document.querySelectorAll(".method-block");
  methodBlocks[0].innerHTML=`<h3>1. Complete Mathematical Model</h3><p>The uptake flux per unit biomass of consumer <i>i</i> for resource <i>α</i> is determined by the selected response function:</p><div class="eq"><b>Monod:</b> uᵢα = cᵢαRα/(Kᵢα+Rα)<br><b>Linear:</b> uᵢα = cᵢαRα</div><div class="eq">dNᵢ/dt = Nᵢ[Σ<sub>α=1</sub><sup>M</sup> Yᵢαuᵢα − mᵢ]</div><div class="eq">dRβ/dt = δβ(Sβ−Rβ) − Σ<sub>i=1</sub><sup>N</sup>Nᵢuᵢβ + Σ<sub>i=1</sub><sup>N</sup>Σ<sub>α=1, α≠β</sub><sup>M</sup>DᵢβαNᵢuᵢα</div><p>The first term represents external supply or environmental turnover of resource Rβ, the second represents its depletion by all consumers, and the third represents production of Rβ after consumers take up other resources Rα. Consumer growth is summed over all M explicit resources, so both initial resources and produced intermediate metabolites can contribute to growth.</p>`;
  methodBlocks[2].innerHTML=`<h3>3. Batch Culture and Continuous Resource Supply</h3><p>When δ=0, there is no external supply, corresponding to closed batch conditions. When δ&gt;0, the resource approaches the external target concentration S, representing continuous resource supply or environmental turnover. The current equations omit consumer washout with fluid outflow and therefore do not constitute a complete chemostat model; add a separate consumer-outflow loss term to simulate a chemostat.</p>`;
  methodBlocks[3].innerHTML=`<h3>4. Symbols, Indices, and Parameters</h3><p><b>i=1,…,N</b> indexes consumers; <b>α=1,…,M</b> indexes an input resource being taken up; and <b>β=1,…,M</b> indexes the resource being solved for or produced. Nᵢ and Rα are state variables, and Nᵢ,0 and Rα,0 are their initial values. Sβ is the external-supply target concentration; δβ is the resource turnover/supply rate; and mᵢ is the consumer maintenance or mortality loss rate. Both δβ and mᵢ have units of time⁻¹. Yᵢα has units of biomass/resource, and Dᵢβα has units of produced Rβ per unit of Rα taken up. Concentration, time, and yield units must be mutually compatible.</p>`;
  methodBlocks[5].innerHTML=`<h3>Scope and Limitations</h3><p>This tool assumes that all utilizable resources contribute additively to growth, making it suitable for resource competition, metabolite reutilization, self-feeding, cross-feeding, and resource cascades. Dᵢβα is a net transformation yield and does not explicitly distinguish intracellular metabolism, active secretion, passive leakage, or release through lysis. The current implementation also omits minimum requirements for essential resources, consumer outflow with the culture medium, strict mass conservation, spatial structure, and evolution.</p>`;

  /* v1.8: equations, parameter definitions, and endpoint outputs match deriv(). */
  document.title = "Generalized Consumer–Resource Model Simulator v1.8";
  document.querySelector("h1 .version").textContent = "v1.8";
  document.querySelector(".footer").textContent = "All calculations are performed locally in the browser";
  document.querySelector("header .formula").innerHTML = `
    uᵢα = cᵢαRα/(Kᵢα+Rα) <span style="font:11px Arial">(Monod)</span>  or  uᵢα = cᵢαRα <span style="font:11px Arial">(Linear)</span><br>
    dNᵢ/dt = Nᵢ[Σ<sub>α=1</sub><sup>M</sup>Yᵢαuᵢα − mᵢ]<br>
    dRβ/dt = δβ(Sβ−Rβ) − Σ<sub>i=1</sub><sup>N</sup>Nᵢuᵢβ + Σ<sub>i=1</sub><sup>N</sup>Σ<sub>α=1, α≠β</sub><sup>M</sup>DᵢβαNᵢuᵢα`;

  document.querySelector(".param-guide .subhead h3").textContent = "Parameter Definitions, Indices, and Units";
  document.querySelector(".param-guide .subhead span").textContent = "correspond directly to the webpage solver";
  document.querySelector(".param-guide-grid").innerHTML = `
    <div class="param-item"><b>i, N</b>: i=1,…,N  is Consumerindices; N also denotes Consumertotal number.<b>Nᵢ</b>  is Consumer i  BiomassConcentration, <b>Nᵢ,0</b> is its initial value.</div>
    <div class="param-item"><b>α, β, M</b>: α=1,…,M indexes the input resource being taken up; β=1,…,M indexes the resource currently being solved for or produced; M is the total number of resources.</div>
    <div class="param-item"><b>Rα, Rα,0</b>: current and initial concentrations of resource α. During random parameter generation, sampled Rα,0 values serve as allocation weights and are scaled so that ΣαRα,0 equals the specified normalized total.</div>
    <div class="param-item"><b>Sβ</b>: Resource β  External Supply Target Concentration; Random generation satisfies  ΣβSβ equals the specified Normalized Total.<b>δβ</b> is its turnover rate/Supply Rate (time⁻¹), δβ=0  represents batch conditions without external supply; δβ not interactionon Consumer.</div>
    <div class="param-item"><b>uᵢα</b>: uptake flux of resource α per unit biomass of consumer i (resource·biomass⁻¹·time⁻¹). The total resource-consumption flux is Nᵢuᵢα.</div>
    <div class="param-item"><b>cᵢα</b>: uptake parameter. In Monod mode, it is the maximum uptake flux per unit biomass; in linear mode, it is the proportionality coefficient relating uᵢα to Rα. Its units therefore differ between modes.</div>
    <div class="param-item"><b>Kᵢα</b>: used only in  Monod  mode as the half-saturation constant, with the same units as  Rα same; Rα=Kᵢα  when  uᵢα=cᵢα/2.not used in linear mode:  Kᵢα.</div>
    <div class="param-item"><b>Yᵢα</b>: biomass yield of consumer i on resource α (biomass/resource). Yᵢαuᵢα is the contribution of that resource to the consumer’s per-biomass growth rate.</div>
    <div class="param-item"><b>mᵢ</b>: maintenance or mortality loss rate of consumer i (time⁻¹); the net per-biomass growth rate is Σ<sub>α=1</sub><sup>M</sup>Yᵢαuᵢα−mᵢ.</div>
    <div class="param-item"><b>Dᵢβα</b>: net transformation yield of Rβ produced after consumer i takes up Rα (produced Rβ/taken-up Rα). The webpage fixes Dᵢαα=0; the production flux is DᵢβαNᵢuᵢα.</div>
    <div class="param-item"><b>Total Time, Output Interval</b>: are the integration endpoint and sampling interval for plots/CSV output, respectively; they do not change model parameters.</div>
    <div class="param-item"><b>Unit requirements:</b> time, biomass, resource concentration, and yield units must be compatible within a simulation. If different resources are represented by mass, molar amount, or carbon equivalents, use a consistent conversion basis.</div>`;

  document.querySelector("#knownPanel > .note").innerHTML = `<b>Hierarchical Parameterization: </b>First use  Aᵢα  to determine Consumerwhether Utilizeeach Substance; Only  Aᵢα=1  edges receive parameters:  cᵢα, Kᵢα  and  Yᵢα.Then use  Pᵢβα  to determine whether uptake of  Rα  produces a product after uptake Rβ; Only  Pᵢβα=1  pathways receive  Dᵢβα.Disabled pathways are treated as  0  in simulation and export.`;
  document.querySelectorAll(".dist-table thead th:nth-child(3)").forEach(el=>el.textContent="Mean/Fixed Value/Normalized Total");
