  document.querySelector("#kTable").closest("section").querySelector(".subhead span").textContent = "Used only in Monod mode; same units as resource concentration";
  document.querySelector("#yTable").closest("section").querySelector(".subhead span").textContent = "Yᵢα: biomass formed by consumer i per unit of resource α taken up";
  distMeta.find(q=>q[1]==="uptake")[7] = "Uptake parameter: maximum uptake flux per unit biomass in Monod mode; concentration-response coefficient in linear mode";
