  distMeta.find(q=>q[1]==="yield")[7] = "Resource-specific Biomass Yield; All M  Resource growth contributions are summed";
  distMeta.find(q=>q[1]==="conversion")[7] = "Consumer-specific net Resource TransformationYield: Input Rα → output Rβ; Dᵢαα=0";

  /* Per-object fixed values for Monte Carlo simulations. */
  const monteRuleSection=$("distRows").closest("section");
  monteRuleSection.insertAdjacentHTML("beforebegin",`<section class="subcard structure-random-card"><div class="subhead"><h3>Network Structure in Random Simulations</h3><span>First sample utilization and production states, then sample metabolic parameters for existing pathwaysParameters</span></div><div class="structure-random-grid"><label>Substance-Utilization Structure<select id="useStructureMode"><option value="random" selected>Randomly determined from probability in each replicate</option><option value="fixed">Use the current fixed  Aᵢα</option></select></label><label>Utilization Probability P(Aᵢα=1)<input id="useProbability" type="number" min="0" max="1" step="0.05" value="0.5"></label><label class="check-option"><input id="ensureOneUse" type="checkbox" checked>Ensure that each consumer utilizes at least one substance</label><label>Metabolite-Production Structure<select id="produceStructureMode"><option value="random" selected>Randomly determined from probability in each replicate</option><option value="fixed">Use the current fixed  Pᵢβα</option></select></label><label>Production Probability P(Pᵢβα=1 | Aᵢα=1)<input id="produceProbability" type="number" min="0" max="1" step="0.05" value="0.2"></label></div><div class="tensor-note">each timesRandom simulationfirst Generate Aᵢα; Only when  Aᵢα=1  are values sampled cᵢα, Kᵢα  and  Yᵢα.Then generate production structure for usable inputs:  Pᵢβα; Only when  Pᵢβα=1  are values sampled Dᵢβα.Fixed-structure mode uses the known-parameter Parameterssection’s current selectionsstatus.</div></section>`);
