  function captureCrmFixed(){document.querySelectorAll("[data-crmfix]").forEach(el=>{const key=el.dataset.crmfix,idx=el.dataset.index.split(",").map(Number),v=Number(el.value);if(idx.length===1)crmFixed[key][idx[0]]=v;else if(idx.length===2){crmFixed[key][idx[0]]??=[];crmFixed[key][idx[0]][idx[1]]=v}else{crmFixed[key][idx[0]]??=[];crmFixed[key][idx[0]][idx[1]]??=[];crmFixed[key][idx[0]][idx[1]][idx[2]]=v}})}
