  function fixedMatrix(key,label){const fixedStructure=$("useStructureMode")?.value==="fixed";return `<div class="crm-fixed-block"><h4>${label}</h4><div class="scroll"><table class="matrix"><thead><tr><th>Consumer↓ / Resource→</th>${Array.from({length:m},(_,a)=>`<th>R${a+1}</th>`).join("")}</tr></thead><tbody>${Array.from({length:n},(_,i)=>`<tr><th>N${i+1}</th>${Array.from({length:m},(_,a)=>{const disabled=fixedStructure&&!U[i][a];return `<td class="${disabled?"inactive-path":""}"><input type="number" data-crmfix="${key}" data-index="${i},${a}" value="${disabled?0:crmFixed[key][i][a]}" min="0" step=".01" ${disabled?"disabled":""}></td>`}).join("")}</tr>`).join("")}</tbody></table></div></div>`}
  function renderCrmFixed(){captureCrmFixed();ensureCrmFixed();const selected=Object.fromEntries(distMeta.map(q=>[q[1],monteDist(q[1])==="fixed"]));let html="",consumerKeys=["n0","mort"].filter(k=>selected[k]),resourceKeys=["r0","supply","dilution"].filter(k=>selected[k]);if(consumerKeys.length)html+=`<div class="crm-fixed-block"><h4>Consumer Parameters</h4><div class="scroll"><table><thead><tr><th>Consumer</th>${consumerKeys.map(k=>`<th>${metaFor(k)[0]}</th>`).join("")}</tr></thead><tbody>${Array.from({length:n},(_,i)=>`<tr><th>N${i+1}</th>${consumerKeys.map(k=>`<td><input type="number" data-crmfix="${k}" data-index="${i}" value="${crmFixed[k][i]}" min="0" step=".01"></td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`;if(resourceKeys.length)html+=`<div class="crm-fixed-block"><h4>Resource and Metabolite Parameters</h4><div class="scroll"><table><thead><tr><th>Resource/Metabolite</th>${resourceKeys.map(k=>`<th>${metaFor(k)[0]}</th>`).join("")}</tr></thead><tbody>${Array.from({length:m},(_,a)=>`<tr><th>R${a+1}</th>${resourceKeys.map(k=>`<td><input type="number" data-crmfix="${k}" data-index="${a}" value="${crmFixed[k][a]}" min="0" step=".01"></td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`;if(selected.uptake)html+=fixedMatrix("uptake","Fixed Uptake Parameters cᵢα");if(selected.half)html+=fixedMatrix("half","Fixed Half-Saturation Constants Kᵢα");if(selected.yield)html+=fixedMatrix("yield","Fixed Biomass Yields Yᵢα");if(selected.conversion)html+=`<div class="crm-fixed-block"><h4>Fixed Resource-Transformation Yields Dᵢβα</h4><div class="crm-fixed-selector"><label>Current Consumer <select id="crmFixedConversionConsumer">${Array.from({length:n},(_,i)=>`<option value="${i}" ${i===crmFixedConversionConsumer?"selected":""}>N${i+1}</option>`).join("")}</select></label><span>row: output Rβ; column: Input Rα; diagonal fixed at 0</span></div><div class="scroll"><table class="matrix"><thead><tr><th>output↓ / Input→</th>${Array.from({length:m},(_,a)=>`<th>R${a+1}</th>`).join("")}</tr></thead><tbody>${Array.from({length:m},(_,b)=>`<tr><th>R${b+1}</th>${Array.from({length:m},(_,a)=>`<td class="${a===b?"diagonal":""}"><input type="number" data-crmfix="conversion" data-index="${crmFixedConversionConsumer},${b},${a}" value="${a===b?0:crmFixed.conversion[crmFixedConversionConsumer][b][a]}" min="0" step=".01" ${a===b?"disabled":""}></td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`;$("crmFixedEditors").innerHTML=html;$("crmFixedCard").classList.toggle("hidden",!html);const sel=$("crmFixedConversionConsumer");if(sel)sel.onchange=()=>{captureCrmFixed();crmFixedConversionConsumer=+sel.value;renderCrmFixed()}}
  const renderCrmFixedBase=renderCrmFixed;
  renderCrmFixed=function(){renderCrmFixedBase();const useFixed=$("useStructureMode")?.value==="fixed",produceFixed=$("produceStructureMode")?.value==="fixed";document.querySelectorAll('[data-crmfix="conversion"]').forEach(el=>{const[i,b,a]=el.dataset.index.split(",").map(Number),disabled=a===b||(useFixed&&!U[i][a])||(produceFixed&&!P[i][b][a]);el.disabled=disabled;el.closest("td")?.classList.toggle("inactive-path",disabled&&a!==b)})};
