  const renderBeforeCrmFixed=render;render=function(){captureCrmFixed();renderBeforeCrmFixed();renderCrmFixed()};
  const resizeBeforeCrmFixed=resize;resize=function(){captureCrmFixed();return resizeBeforeCrmFixed()};
  randomModel=function(){captureCrmFixed();ensureCrmFixed();const value=(key,...idx)=>{if(monteDist(key)==="fixed"){let x=crmFixed[key];idx.forEach(i=>x=x[i]);return x}return sampleCfg(metaFor(key))},pUse=clamp(Number($("useProbability").value)||0,0,1),pProduce=clamp(Number($("produceProbability").value)||0,0,1),use=$("useStructureMode").value==="fixed"?cloneMatrix(U):Array.from({length:n},()=>Array.from({length:m},()=>Math.random()<pUse));if($("useStructureMode").value==="random"&&$("ensureOneUse").checked)use.forEach(row=>{if(!row.some(Boolean)&&m)row[Math.floor(Math.random()*m)]=true});const prod=$("produceStructureMode").value==="fixed"?cloneMaskTensor(P).map((byOutput,i)=>byOutput.map(row=>row.map((v,a)=>v&&use[i][a]))):Array.from({length:n},(_,i)=>Array.from({length:m},(_,b)=>Array.from({length:m},(_,a)=>a!==b&&use[i][a]&&Math.random()<pProduce))),sp=Array.from({length:n},(_,i)=>({name:`Consumer ${i+1}`,n0:value("n0",i),m:value("mort",i)})),rs=Array.from({length:m},(_,a)=>({name:a===0?"Primary resource":`Metabolite ${a}`,r0:value("r0",a),s:value("supply",a),d:value("dilution",a)})),c=Array.from({length:n},(_,i)=>Array.from({length:m},(_,a)=>use[i][a]?value("uptake",i,a):0)),k=Array.from({length:n},(_,i)=>Array.from({length:m},(_,a)=>use[i][a]?value("half",i,a):0)),y=Array.from({length:n},(_,i)=>Array.from({length:m},(_,a)=>use[i][a]?value("yield",i,a):0)),t=Array.from({length:n},(_,i)=>Array.from({length:m},(_,b)=>Array.from({length:m},(_,a)=>prod[i][b][a]?value("conversion",i,b,a):0)));if(monteDist("r0")!=="fixed")normalizeResourceTotals(rs,resourceTotal("r0",false),rs.reduce((s,q)=>s+q.s,0));if(monteDist("supply")!=="fixed")normalizeResourceTotals(rs,rs.reduce((s,q)=>s+q.r0,0),resourceTotal("supply",false));validate(sp,rs,c,k,y,t,use,prod);return{sp,rs,c,k,y,t,use,prod}};
