  const endpointStyle=document.createElement("style");
  endpointStyle.textContent=`.endpoint-card{padding:14px}.endpoint-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.endpoint-panel{border:1px solid var(--line);border-radius:8px;background:#fffdf8;padding:10px;min-width:0}.endpoint-panel.endpoint-wide{grid-column:1/-1}.endpoint-panel h3{font-size:14px;margin:0}.endpoint-panel .endpoint-unit{font-size:10px;color:var(--muted);margin-top:3px}.endpoint-panel canvas{width:100%;height:auto;min-height:230px;margin-top:6px}.endpoint-table-wrap{margin-top:12px;max-height:390px;overflow:auto;border:1px solid var(--line);border-radius:8px}.endpoint-table th{position:sticky;top:0;z-index:1}.endpoint-table td:nth-child(2){text-align:left}.endpoint-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.endpoint-actions .status{white-space:nowrap}@media(max-width:760px){.endpoint-grid{grid-template-columns:1fr}.endpoint-panel.endpoint-wide{grid-column:auto}}`;
